/* Cheque lifecycle preview: status, reason, source, bank movement and edit/cancel. */
const {chromium}=require('playwright');const {expect}=require('playwright/test');const assert=require('node:assert/strict');const fs=require('node:fs');const path=require('node:path');
const sizes=process.env.DEEP_AUDIT_SMOKE?[[390,844]]:[[320,700],[360,800],[390,844],[430,932],[768,1024],[1024,768],[1280,800],[1440,900]],languages=process.env.DEEP_AUDIT_SMOKE?['English + Bangla']:['English','English + Bangla','Bangla'];
const output=process.env.DEEP_AUDIT_OUTPUT||'.superpowers/deep-audit/cheque-lifecycle',results=[];
async function main(){const {createServer}=await import('vite');const server=await createServer({cacheDir:'.superpowers/cheque-lifecycle-cache',server:{host:'127.0.0.1',port:4494,strictPort:true}});await server.listen();const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});fs.mkdirSync(output,{recursive:true});
try{for(const [width,height]of sizes)for(const theme of ['light','dark'])for(const language of languages){const id=[width,theme,language.replaceAll(' ','')].join('-');const context=await browser.newContext({viewport:{width,height},hasTouch:width<=1024,reducedMotion:'reduce',colorScheme:theme});await context.addInitScript(({theme,language})=>{localStorage.setItem('hisabiq-theme',theme);localStorage.setItem('hisabiq-erp-personal-v1',JSON.stringify({mode:'Simple',language,density:'Compact',terminology:'simple',dateView:'transaction'}));},{theme,language});await context.tracing.start({screenshots:true,snapshots:true,sources:true});const page=await context.newPage();page.setDefaultTimeout(15000);page.setDefaultNavigationTimeout(60000);await page.route('https://fonts.googleapis.com/**',r=>r.abort());const errors=[];page.on('pageerror',e=>errors.push(e.message));
const w=(en,bn)=>language==='Bangla'?bn:en,act=e=>width<=1024?e.tap():e.click(),button=(r,en,bn)=>r.getByRole('button',{name:w(en,bn),exact:true});
const field=(d,en,bn)=>d.locator('label').filter({hasText:new RegExp('^'+w(en,bn))}).getByRole('textbox');const dialog=()=>page.getByRole('dialog');const tab=async(en,bn)=>act(page.getByRole('tab',{name:w(en,bn),exact:true}));
let visit=0;const go=()=>page.goto('http://127.0.0.1:4494/?case='+(++visit)+'#/app/finance',{waitUntil:'domcontentloaded'});
const bankBalance=async()=>{await tab('Money Accounts','টাকার হিসাব');const card=page.locator('p').filter({hasText:/^Dutch-Bangla Bank · 4582$/}).locator('xpath=ancestor::div[contains(@class,"rounded-xl")][1]');return Number((await card.innerText()).match(/৳([\d,]+(?:\.\d+)?)/)[1].replaceAll(',',''));};
const openCheque=async(number)=>{await tab('Cheques','চেক');const row=page.locator('tbody tr').filter({hasText:number});await act(row.getByRole('button').last());await expect(dialog()).toBeVisible();};
const close=async()=>{await act(button(dialog(),'Close','বন্ধ করুন').first());await expect(dialog()).toBeHidden();};
const transition=async(label,bn,status,statusBn,reason)=>{await act(button(dialog(),label,bn));const confirm=button(dialog(),'Confirm '+status,'নিশ্চিত করুন: '+statusBn);if(reason){await act(confirm);await expect(confirm).toBeVisible();await field(dialog(),'Reason','কারণ').fill(reason);}await act(confirm);await expect(dialog()).toContainText(w(status,statusBn));};
const check=async(name,run)=>{try{await go();await run();assert.deepEqual(errors,[]);results.push({id,name,status:'passed'});}catch(e){results.push({id,name,status:'failed',error:e.message});console.error(id,name,e.message);await page.screenshot({path:path.join(output,id+'-'+name+'.png'),fullPage:true});}};
await check('edit-cancel-save-reopen',async()=>{await openCheque('458923');const d=dialog();await act(button(d,'Edit','সংশোধন'));await field(d,'Bank','ব্যাংক').fill('UNSAVED BANK');await field(d,'Party','পক্ষ').fill('UNSAVED PARTY');await act(button(d,'Cancel','বাতিল'));await act(button(d,'Edit','সংশোধন'));await expect(field(d,'Bank','ব্যাংক')).toHaveValue('Islami Bank Bangladesh');await expect(field(d,'Party','পক্ষ')).toHaveValue('Rahman Hardware');await field(d,'Bank','ব্যাংক').fill('');await act(button(d,'Save cheque','চেক সংরক্ষণ'));await expect(field(d,'Bank','ব্যাংক')).toBeVisible();await field(d,'Bank','ব্যাংক').fill('Saved bank metadata');await field(d,'Reference','রেফারেন্স').fill('QA-EDIT');await act(button(d,'Save cheque','চেক সংরক্ষণ'));await expect(d).toContainText('Saved bank metadata');await close();await openCheque('458923');await expect(d).toContainText('QA-EDIT');await expect(d).toContainText('Saved bank metadata');await expect(d).toContainText('35,000');await page.keyboard.press('Escape');await expect(d).toBeHidden();});
await check('received-deposit-clear-once',async()=>{const before=await bankBalance();await openCheque('458923');await act(button(dialog(),'Mark deposited','জমা হয়েছে'));await act(button(dialog(),'Back','ফিরুন'));await close();assert.equal(await bankBalance(),before);await openCheque('458923');await transition('Mark deposited','জমা হয়েছে','Deposited','ব্যাংকে জমা');await close();assert.equal(await bankBalance(),before,'deposit does not move money');await openCheque('458923');await transition('Mark cleared','ক্লিয়ার হয়েছে','Cleared','ক্লিয়ার হয়েছে');await expect(button(dialog(),'Edit','সংশোধন')).toHaveCount(0);await close();assert.equal(await bankBalance(),before+35000);await openCheque('458923');await expect(button(dialog(),'Mark cleared','ক্লিয়ার হয়েছে')).toHaveCount(0);await close();assert.equal(await bankBalance(),before+35000,'terminal reopen does not double-clear');});
await check('issued-clear-and-bank-eligibility',async()=>{const before=await bankBalance();await openCheque('091144');await act(button(dialog(),'Edit','সংশোধন'));const bank=dialog().locator('label').filter({hasText:new RegExp('^'+w('Money account','টাকার হিসাব'))}).getByRole('combobox');await act(bank);await expect(page.getByRole('listbox')).toBeVisible();await expect(page.getByRole('option',{name:'Main Cash Counter',exact:true})).toHaveCount(0);await act(page.getByRole('option',{name:w('Select bank account','ব্যাংক হিসাব বাছুন'),exact:true}));await act(button(dialog(),'Save cheque','চেক সংরক্ষণ'));await act(button(dialog(),'Mark cleared','ক্লিয়ার হয়েছে'));const confirm=button(dialog(),'Confirm Cleared','নিশ্চিত করুন: ক্লিয়ার হয়েছে');await act(confirm);await expect(confirm).toBeVisible();await expect(dialog()).toContainText(w('Presented','ব্যাংকে উপস্থাপিত'));await act(button(dialog(),'Back','ফিরুন'));await act(button(dialog(),'Edit','সংশোধন'));await act(bank);await expect(page.getByRole('listbox')).toBeVisible();await act(page.getByRole('option',{name:'Dutch-Bangla Bank · 4582',exact:true}));await act(button(dialog(),'Save cheque','চেক সংরক্ষণ'));await transition('Mark cleared','ক্লিয়ার হয়েছে','Cleared','ক্লিয়ার হয়েছে');await close();assert.equal(await bankBalance(),before-22000);});
await check('reason-and-terminal-actions',async()=>{const before=await bankBalance();await openCheque('458923');await transition('Return cheque','চেক ফেরত','Returned','ফেরত','QA return reason');await expect(dialog()).toContainText('QA return reason');await expect(button(dialog(),'Edit','সংশোধন')).toHaveCount(0);await close();assert.equal(await bankBalance(),before);await openCheque('091144');await transition('Stop payment','পেমেন্ট বন্ধ করুন','Stopped','পেমেন্ট বন্ধ','QA stop reason');await expect(dialog()).toContainText('QA stop reason');if([390,1440].includes(width)){await page.addScriptTag({path:require.resolve('axe-core/axe.min.js')});const violations=await page.evaluate(async()=>{const r=await axe.run(document.querySelector('[data-dialog-root]'),{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa']}});return r.violations.map(v=>({id:v.id,nodes:v.nodes.map(n=>n.target)}));});assert.deepEqual(violations,[],'cheque terminal dialog axe');}await close();assert.equal(await bankBalance(),before);});
await check('received-bounce-cancel-and-deposited-return',async()=>{
 let before=await bankBalance();await openCheque('458923');await transition('Mark deposited','জমা হয়েছে','Deposited','ব্যাংকে জমা');await transition('Mark bounced','চেক বাউন্স হয়েছে','Bounced','চেক ফেরত এসেছে','QA bounced');await close();assert.equal(await bankBalance(),before);
 await go();before=await bankBalance();await openCheque('458923');await transition('Cancel cheque','চেক বাতিল','Cancelled','বাতিল','QA cancelled');await close();assert.equal(await bankBalance(),before);
 await go();before=await bankBalance();await openCheque('458923');await transition('Mark deposited','জমা হয়েছে','Deposited','ব্যাংকে জমা');await transition('Return cheque','চেক ফেরত','Returned','ফেরত','QA deposited return');await close();assert.equal(await bankBalance(),before);
});
await check('new-issued-present-return-stop-cancel',async()=>{
 const before=await bankBalance();
 const issued=async(number)=>{await tab('Cheques','চেক');await act(button(page,'New cheque','নতুন চেক').first());const d=dialog();await field(d,'Cheque number','চেক নম্বর').fill(number);await field(d,'Bank','ব্যাংক').fill('QA Bank');await field(d,'Received from','কার কাছ থেকে পেয়েছি').fill('QA Supplier');await field(d,'Amount','টাকা').fill('123');const type=d.locator('label').filter({hasText:new RegExp('^'+w('Cheque type','চেকের ধরন'))}).getByRole('combobox');await act(type);await expect(page.getByRole('listbox')).toBeVisible();await act(page.getByRole('option',{name:w('Issued','দিয়েছি'),exact:true}));await act(button(d,'Save cheque','চেক সংরক্ষণ'));await expect(d).toBeHidden();await openCheque(number);};
 await issued('QA-ISSUED-1');await transition('Mark presented','উপস্থাপিত হয়েছে','Presented','ব্যাংকে উপস্থাপিত');await transition('Mark returned','চেক ফেরত দেখান','Returned','ফেরত','QA issued return');await close();assert.equal(await bankBalance(),before);
 // The creation form preserves its direction and draft after save, so return to Received before reusing the helper.
 await go();await issued('QA-ISSUED-2');await transition('Stop payment','পেমেন্ট বন্ধ করুন','Stopped','পেমেন্ট বন্ধ','QA issued stop');await close();assert.equal(await bankBalance(),before);
 await go();await issued('QA-ISSUED-3');await transition('Cancel cheque','চেক বাতিল','Cancelled','বাতিল','QA issued cancel');await close();assert.equal(await bankBalance(),before);
});
await context.tracing.stop(results.some(r=>r.id===id&&r.status==='failed')?{path:path.join(output,id+'.zip')}:{});await context.close();console.log(id,results.filter(r=>r.id===id).map(r=>r.name+':'+r.status).join(','));}}
finally{fs.writeFileSync(path.join(output,'results.json'),JSON.stringify(results,null,2));await browser.close();await server.close();}console.log(results.length+' journeys; '+results.filter(r=>r.status==='failed').length+' failed');assert.equal(results.filter(r=>r.status==='failed').length,0);}
main().catch(e=>{console.error(e);process.exitCode=1});
